<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($umkm['name'])?></title><link rel="stylesheet" href="<?=base_url('public/assets/css/template4.css')?>"></head><body><header><div class="brand">🌿 <?=e($umkm['name'])?></div><nav><a href="#home">Home</a><a href="#products">Products</a><a href="#gallery">Gallery</a><a href="#testi">Reviews</a><a href="#contact">Contact</a></nav></header><section id="home" class="hero"><div class="shape"><div><small>FRESH · NATURAL · LOCAL</small><h1><?=e($umkm['hero_title'])?></h1><p><?=e($umkm['hero_text'])?></p><a href="#products">Shop Flowers</a></div></div><?php if($umkm['hero_image']): ?><img src="<?=base_url('public/'.$umkm['hero_image'])?>"><?php endif; ?></section><section class="intro"><h2>Flowers that brighten ordinary days.</h2><p><?=e($umkm['description'])?></p></section><section id="products" class="products"><h2>Best Sellers</h2><div class="grid"><?php foreach($products as $p): ?><article><?php if($p['image']): ?><img src="<?=base_url('public/'.$p['image'])?>"><?php endif; ?><h3><?=e($p['name'])?></h3><p><?=e($p['description'])?></p><b><?=money($p['price'])?></b></article><?php endforeach; ?></div></section><section id="testi" class="reviews"><h2>What customers say</h2><?php foreach($testimonials as $t): ?><blockquote>“<?=e($t['message'])?>”<footer>— <?=e($t['name'])?></footer></blockquote><?php endforeach; ?></section><section id="gallery" class="gallery"><h2>Our Gallery</h2><div><?php foreach($gallery as $g): ?><img src="<?=base_url('public/'.$g['image'])?>"><?php endforeach; ?></div></section><footer id="contact"><h2>Let's bloom together.</h2><p><?=e($umkm['address'])?> · <?=e($umkm['hours'])?></p><a href="https://wa.me/<?=preg_replace('/\D/','',$umkm['phone'])?>">Chat WhatsApp</a></footer></body></html>
